WITH total_orders AS ( SELECT cliente, COUNT(DISTINCT pedido) AS total_orders FROM itens WHERE mes LIKE '2026-%' GROUP BY cliente ), canceled_orders AS ( SELECT cliente, COUNT(DISTINCT pedido) AS canceled_orders FROM itens WHERE tipo = 'cancelamento' AND mes LIKE '2026-%' GROUP BY cliente ) SELECT t.cliente, ROUND(100.0 * c.canceled_orders / t.total_orders, 1) AS percent_cancelado FROM total_orders t JOIN canceled_orders c ON t.cliente = c.cliente WHERE t.total_orders > 0 ORDER BY percent_cancelado DESC LIMIT 1;